use kimo_core::{color::output_audit,effects::Frame,model::Project};
#[test]fn audit_distinguishes_pq_bounds(){let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=1;p.color_pipeline.output_gamut=1;p.color_pipeline.output_transfer=6;let f=Frame{w:2,h:1,d:vec![-0.25,4.,101.,1.,0.18,0.18,0.18,1.]};let v=output_audit::audit(&p,&f).unwrap();assert_eq!(v["working_linear"]["below_zero_rgb"][0],1);assert_eq!(v["above_pq10000nit_rgb_pixels_before_mapping"],1);assert_eq!(v["configured_encoded_output"]["below_zero_rgb"][0],0);assert_eq!(v["configured_encoded_output"]["above_one_rgb"][2],0);}
#[test]fn audit_empty_legacy(){let f=Frame{w:0,h:0,d:vec![]};let mut p=Project::default();assert!(output_audit::audit(&p,&f).is_err());p.color_pipeline.enabled=true;let v=output_audit::audit(&p,&f).unwrap();assert!(v["working_linear"]["min_rgb"].is_null());}
#[test]fn audit_encoded_exact_pipeline(){let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=3;p.color_pipeline.output_gamut=0;p.color_pipeline.output_transfer=1;let f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,1.]};let v=output_audit::audit(&p,&f).unwrap();let mut ref_f=Frame{w:1,h:1,d:f.d.clone()};kimo_core::color::pipeline::output(&p,&mut ref_f).unwrap();for j in 0..3{assert_eq!(v["configured_encoded_output"]["max_rgb"][j].as_f64().unwrap(),ref_f.d[j] as f64);}}
#[test]fn gamut_overlay_stage_colors(){let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=0;let f=Frame{w:3,h:1,d:vec![-0.1,0.2,0.3,1.,2.,0.2,0.3,1.,-0.1,2.,0.3,1.]};let(q,v)=output_audit::gamut_overlay(&p,&f,1.).unwrap();assert_eq!(v["negative_only_pixels"],1);assert_eq!(v["above_ceiling_only_pixels"],1);assert_eq!(v["both_pixels"],1);assert_eq!(&q.d[..3],&[0.,0.25,1.]);assert_eq!(&q.d[8..11],&[1.,0.,1.]);p.color_pipeline.output_transfer=6;assert!(output_audit::gamut_overlay(&p,&f,1.).is_err());}

#[test]fn overlay_hostile_alpha_and_shape(){let mut p=Project::default();p.color_pipeline.enabled=true;for a in [-0.1,1.01,f32::NAN,f32::INFINITY]{let f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,a]};assert!(output_audit::gamut_overlay(&p,&f,1.).is_err());}for n in [0,1,5]{let f=Frame{w:1,h:1,d:vec![0.5;n]};assert!(output_audit::gamut_overlay(&p,&f,1.).is_err());}}
